import{_ as e,o as a,c as i,ag as r}from"./chunks/framework.BIas3y6W.js";const c=JSON.parse(`{"title":"Home","description":"","frontmatter":{"layout":"home","title":"Home","hero":{"name":"Building Apps with AI","text":"Build real software with AI, on a $0 budget.","tagline":"A hands-on University of Idaho course for students from any major who have taken one programming course. You ship a deployed web app by directing AI tools, and learn the habits that make that software trustworthy. 3 credits · a 16-week semester · two 75-minute studios a week.","actions":[{"theme":"brand","text":"Start here (first hour)","link":"/setup/#before-studio-1"},{"theme":"alt","text":"Read the syllabus","link":"/SYLLABUS"},{"theme":"alt","text":"Browse the weeks","link":"/weeks/01-hello-vibe-coding/"}]},"features":[{"title":"Very hands-on","details":"Two 75-minute studios a week. Studio A is a short talk (15 minutes at most) and a lab; Studio B is a workshop with practice, project time and help. You ship five projects.","link":"/projects/","linkText":"See the projects"},{"title":"Free tools only","details":"Every required tool has a free tier, and every layer has two tested fallbacks for when free limits run out.","link":"/TOOLS","linkText":"The tool handout"},{"title":"One workflow, every tool","details":"The Safe Loop — describe, plan, step, test, read, commit — works in a chat window in week 1 and with an AI agent in weeks 11–16.","link":"/resources/safe-loop","linkText":"The Safe Loop"},{"title":"Graded on understanding, with support","details":"Labs and timed builds are graded on effort, not polish or speed, and exit tickets aren't graded on correctness. Three short, friendly walkthroughs, with the questions published in advance, let you show what you understand. Walkthroughs 1 and 2 can be retaken.","link":"/assessment/oral-walkthroughs#what-to-expect","linkText":"What to expect"},{"title":"Safety built in","details":"Nine plain-English safety rules, each taught when you need it, and a week 13 lab where you test your own database the way an attacker would, then lock it down.","link":"/setup/safety-contract","linkText":"The safety contract"},{"title":"Based on evidence","details":"Designed from a review of 2025–26 university and industry courses, education research and real security incidents, updated in October 2026.","link":"/research/design-rationale","linkText":"Why it looks like this"}]},"headers":[],"relativePath":"index.md","filePath":"index.md"}`),s={name:"index.md"};function o(d,t,n,h,l,p){return a(),i("div",null,[...t[0]||(t[0]=[r('<h2 id="the-16-weeks" tabindex="-1">The 16 weeks <a class="header-anchor" href="#the-16-weeks" aria-label="Permalink to &quot;The 16 weeks&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Week</th><th>Title</th><th>You build</th></tr></thead><tbody><tr><td>0</td><td><a href="/building-apps-with-ai/setup/">Pre-work</a></td><td>Accounts, privacy settings and a first AI-built page, before Studio 1</td></tr><tr><td>1</td><td><a href="/building-apps-with-ai/weeks/01-hello-vibe-coding/">Hello, Vibe Coding</a></td><td>A personal page built in a chat preview, explained, and changed by hand</td></tr><tr><td>2</td><td><a href="/building-apps-with-ai/weeks/02-ship-your-page/">Ship Your Page</a></td><td>Your home page, live on the web, and your own AI-use rules</td></tr><tr><td>3</td><td><a href="/building-apps-with-ai/weeks/03-prompting-and-save-points/">Prompting &amp; Save Points</a></td><td>A browser game in one hour, with git save points</td></tr><tr><td>4</td><td><a href="/building-apps-with-ai/weeks/04-undo-compare-explain/">Undo, Compare, Explain</a></td><td>A rollback, a two-model comparison and your first automated test</td></tr><tr><td>5</td><td><a href="/building-apps-with-ai/weeks/05-spec-first/">Spec First</a></td><td>A one-page spec for Project 1</td></tr><tr><td>6</td><td><a href="/building-apps-with-ai/weeks/06-spec-to-app/">From Spec to App</a></td><td>Project 1 from your own spec, after an app-builder bake-off</td></tr><tr><td>7</td><td><a href="/building-apps-with-ai/weeks/07-read-and-debug/">Read It, Debug It</a></td><td>The Debug Clinic (AI off) and edge-case tests</td></tr><tr><td>8</td><td><a href="/building-apps-with-ai/weeks/08-own-it/">Own It</a></td><td>A function you write yourself, tests of your logic, Project 1 final</td></tr><tr><td>9</td><td><a href="/building-apps-with-ai/weeks/09-apis-and-secrets/">APIs &amp; Secrets</a></td><td>An AI-powered micro-app with a hidden API key</td></tr><tr><td>10</td><td><a href="/building-apps-with-ai/weeks/10-servers-and-deployment/">Servers &amp; Deployment</a></td><td>The micro-app, deployed, with the key provably secret</td></tr><tr><td>11</td><td><a href="/building-apps-with-ai/weeks/11-agents/">How Agents Work</a></td><td>&quot;Be the Agent&quot;; your capstone&#39;s first agent-built feature</td></tr><tr><td>12</td><td><a href="/building-apps-with-ai/weeks/12-pull-requests/">Pull Requests &amp; Agent Code</a></td><td>Capstone features merged through pull requests</td></tr><tr><td>13</td><td><a href="/building-apps-with-ai/weeks/13-data-and-access/">Data &amp; Access Rules</a></td><td>The RLS Attack Lab; a database for your capstone</td></tr><tr><td>14</td><td><a href="/building-apps-with-ai/weeks/14-security-and-review/">Security &amp; Review</a></td><td>A security sweep and a pull-request review</td></tr><tr><td>15</td><td><a href="/building-apps-with-ai/weeks/15-ship-it/">Ship It</a></td><td>Capstone polish and a demo video</td></tr><tr><td>16</td><td><a href="/building-apps-with-ai/weeks/16-project-fair/">Project Fair</a></td><td>Finals week: the Project Fair</td></tr></tbody></table><h2 id="the-safe-loop" tabindex="-1">The Safe Loop <a class="header-anchor" href="#the-safe-loop" aria-label="Permalink to &quot;The Safe Loop&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>Step</th><th>What you do</th></tr></thead><tbody><tr><td>1</td><td><strong>Describe</strong></td><td>Goal, context, constraints, &quot;done when&quot;. Write the check first</td></tr><tr><td>2</td><td><strong>Plan</strong></td><td>Ask for a plan, and edit it before any code is written</td></tr><tr><td>3</td><td><strong>Step</strong></td><td>One small change at a time</td></tr><tr><td>4</td><td><strong>Test</strong></td><td>Run your check, the normal case and an edge case</td></tr><tr><td>5</td><td><strong>Read</strong></td><td>Read the diff, and write a short teach-back of what changed and why</td></tr><tr><td>6</td><td><strong>Commit</strong></td><td>A git save point with a clear message</td></tr></tbody></table><p>If two fixes in a row fail, stop, start a fresh chat and rewrite the prompt: the <strong>two-strikes rule</strong>. <a href="/building-apps-with-ai/resources/safe-loop.html">Printable card</a>.</p><h2 id="how-to-use-this-site" tabindex="-1">How to use this site <a class="header-anchor" href="#how-to-use-this-site" aria-label="Permalink to &quot;How to use this site&quot;">​</a></h2><ul><li><strong>Students:</strong> start with the <a href="/building-apps-with-ai/setup/#before-studio-1">first-hour quick start</a> before Studio 1. Each week, open the week&#39;s overview and read <strong>This week at a glance</strong> first: it lists what to do before Studio A, what each studio covers, what&#39;s due and the minimum to keep up. Keep <a href="/building-apps-with-ai/resources/troubleshooting.html">troubleshooting</a> and the <a href="/building-apps-with-ai/resources/glossary.html">glossary</a> handy.</li><li><strong>Self-paced learners:</strong> follow the <a href="/building-apps-with-ai/resources/self-paced.html">self-paced path</a>, which says what replaces each studio activity when you&#39;re working alone. When you&#39;re stuck, use <a href="/building-apps-with-ai/resources/tutor-mode.html">tutor mode</a>.</li><li><strong>Screen reader or keyboard users:</strong> the <a href="/building-apps-with-ai/resources/accessibility.html">accessibility guide</a> covers every tool the course uses.</li><li><strong>Instructors:</strong> instructor notes, answer keys and the instructor guide are in the course&#39;s private source repository. To teach the course, ask Boyu Zhang for access.</li></ul><div class="tip custom-block"><p class="custom-block-title">Tools change often</p><p>Every price, limit and model name lives on one page, <a href="/building-apps-with-ai/TOOLS.html">Tools</a>, which carries the date it was last checked.</p></div><p class="vc-license">Course materials: <a href="https://github.com/Boyu-Zhang-UOI/building-apps-with-ai/blob/main/LICENSE">CC BY 4.0</a> · Code: <a href="https://github.com/Boyu-Zhang-UOI/building-apps-with-ai/blob/main/LICENSE-CODE">MIT</a></p>',9)])])}const w=e(s,[["render",o]]);export{c as __pageData,w as default};
